import json,math,hashlib
from collections import Counter,defaultdict
from vs import corpus,generators,ivtff,refcorpus
BOOKS=('it_dante','es_buenamor','en_paston','medieval_czech_01473c19')
def regress(x,y):
 if len(x)<30:return None
 mx=sum(x)/len(x);my=sum(y)/len(y)
 vx=sum((a-mx)**2 for a in x);vy=sum((b-my)**2 for b in y)
 if not vx or not vy:return None
 cov=sum((a-mx)*(b-my) for a,b in zip(x,y))
 return {'n':len(x),'slope':cov/vx,'r':cov/math.sqrt(vx*vy)}
N=30000

def measure(words):
 counts=Counter(words);tp=Counter(); yp=Counter();tp['']=len(words)
 for w,c in counts.items():
  for i in range(1,len(w)+1):tp[w[:i]]+=c;yp[w[:i]]+=1
 groups=defaultdict(lambda:[[],[],[],[]]); details=Counter()
 for w,c in counts.items():
  L=len(w)
  if L not in range(4,9):continue
  up=next((i for i in range(1,L+1) if yp[w[:i]]==1),L+1)
  values=[]
  for i in range(1,up+1):
   den=tp[w[:i-1]]-c
   num=tp[w[:i]]-c if i<=L else 0
   values.append(-math.log2((num+1)/(den+1)))
  v=groups[L]; v[0].append(math.log2(c/N));v[1].append(up/L);v[2].append(sum(values)/len(values));v[3].append(1 if up>L else 0)
  details['boundary_only']+=up>L
 result={}
 for l,(x,u,info,bd) in sorted(groups.items()):
  result[str(l)]={'types':len(x),'boundary':sum(bd),'up':regress(x,u),'smoothed_information':regress(x,info)}
 return result

def valid(pages):return [w for p in pages for l in p.lines for w in l.words if not ivtff.uncertain(w) and w.isascii() and w.isalpha() and w.islower()][:N]

out={}
for trans in ('zl','it'):
 train,_=corpus.split_pages('practice',trans)
 words=valid(train);assert len(words)==N
 out[trans]=measure(words)
 for name in ('self_citation','grille','line_chain'):
  fn=getattr(generators,'g_'+name)
  for seed in range(1,6):
   words=valid(fn(train,train,seed=seed));assert len(words)==N
   out[f'{trans}-{name}-{seed}']=measure(words)
for book in BOOKS:
 entry=next(e for e in refcorpus.pins() if e['id']==book)
 with open(entry['file'],'rb') as f:assert hashlib.sha256(f.read()).hexdigest()==entry['sha256']
 words=' '.join(refcorpus.blocks_of(book)).split()
 for i in range(3):out[f'{book}-{i+1}']=measure(words[i*N:(i+1)*N])
print(json.dumps(out,indent=2))
